711	    /**
712	     * Whether this planet stands no defence at all: the state the doctrine's floor is written for,
713	     * and the one the economy's saving must not veto.
714	     */
715	    private function holdsNoDefence(PlanetService $planet): bool
716	    {
717	        return $planet->getDefenseUnits()->getAmount() === 0;
718	    }
