720	    /**
721	     * Whether one planet of the account stands no wall while a sibling already holds one: the state
722	     * the wall order above is spent on, and the one that outranks adding wall anywhere else.
723	     *
724	     * @param  array<int, PlanetService>  $planets
725	     */
726	    private function nakedBesideWalled(array $planets): bool
727	    {
728	        $walled = false;
729	        $bare = false;
730	        // A sibling counts as walled the moment it is paid for, for the same reason the wall order
731	        // above reads its own yard: the invariant is read on built units, so the account leaves its
732	        // opening when the first order is placed.
733	
734	        foreach ($planets as $planet) {
735	            if ($this->defenseNeed->standingUnits($planet) > 0) {
736	                $walled = true;
737	
738	                continue;
739	            }
740	
741	            $bare = true;
742	        }
743	
744	        return $walled && $bare;
745	    }
746	
747	    /**
748	     * Whether any planet of the account stands a wall at all: the state that says the opening is over,
749	     * so the floor of a sibling holding nothing outranks the account's habits rather than waiting on
750	     * them.
751	     *
752	     * @param  array<int, PlanetService>  $planets
753	     */
754	    private function anyPlanetHoldsDefence(array $planets): bool
755	    {
756	        foreach ($planets as $planet) {
757	            // A wall already paid for in the yard counts here for the same reason it counts in the
758	            // pass above: the account has left its opening the moment its first wall is bought, so
759	            // the bare siblings are served from that login on rather than one session behind the
760	            // homeworld's queue (measured live 2 Oct 2026: a sibling left at zero defence while the
761	            // account's only wall sat in the yard).
762	            if ($this->defenseNeed->standingUnits($planet) > 0) {
763	                return true;
764	            }
765	        }
766	
767	        return false;
768	    }
769	
770	    /**
771	     * The first wall a planet that holds nothing takes.
772	     *
773	     * The doctrine names the shape, but only among units this planet's yard can actually build: a
774	     * mid-game doctrine's ratio names nothing below a level-two shipyard, while the anchor it could
775	     * build is not in the ratio at all. A young colony's yard sits below every one of them, so the
776	     * composition answered null and the planet stayed naked beside a sibling's wall however often the
777	     * session offered it (measured live 2 Oct 2026: one planet at zero defence beside a sibling
778	     * holding 1,496). The fallback is the host's own cheapest defence unit, so no unit is named here.
779	     */
780	    private function standingDefence(PlayerService $player, PlanetService $planet): ?QueueableUnit
781	    {
782	        $need = $this->defenseNeed->evaluate($player, $planet);
783	        if ($need === null) {
784	            return $this->cheapestQueueableDefence($planet, null);
785	        }
786	
787	        $defense = $this->defenseComposition->plan($player, $planet, $need);
788	        if ($defense !== null && $this->requirementsMet($planet, $defense->unit)) {
789	            // The host refuses an order it cannot pay for whole (QueueUnits: queue_not_created), and a
790	            // planet whose plan repeats that refusal every login stays naked forever, so the order is
791	            // capped by what this planet can actually pay for right now.
792	            $amount = min($defense->amount, $this->affordable($planet, $defense->unit));
793	            if ($amount >= self::FIRST_CARGO_AMOUNT) {
794	                return $this->unit($planet, $defense->unit, 'role:defense:standing:'.$defense->unit->machine_name, $amount, true);
795	            }
796	        }
797	
798	        return $this->cheapestQueueableDefence($planet, $need);
799	    }
