801	    /**
802	     * The wall order every bare sibling of the account owes, in planet order.
803	     *
804	     * A player with several naked colonies clicks through all of them before logging off, and the
805	     * invariant reads the account, so one login has to reach them all: a pass that returned a single
806	     * sibling per login needed as many logins as the account has planets, which is longer than its
807	     * own day of sessions, and the cohort read still found planets at zero beside a sibling holding
808	     * a wall (QUAL-003: 3 planets at zero defence while one held 1,312 units). Each order names its
809	     * own planet, so the schedule places them on the planets that stand bare, whatever the login chose.
810	     *
811	     * The order a bare sibling takes is the wall itself when its own yard can build it, and the
812	     * building planner's wall prerequisites stand the yard when it cannot: a login that finds a
813	     * sibling naked beside a wall spends itself on that sibling before the account's habits. Each
814	     * order names the planet it belongs to, so the executor places it on that planet and not on
815	     * whichever planet the login happened to open.
816	     *
817	     * Only an account that already holds a wall somewhere is served: while no wall stands anywhere
818	     * the account is in its opening, where cargo, the colony ship and the probe come first, and the
819	     * standing pass below still reaches the floor once a wall exists. A planet already paid for in
820	     * the yard is no longer bare and is left for the next login.
821	     *
822	     * A sibling whose own yard cannot take the wall yet is left to the building planner: the order
823	     * this pass can place is a defence unit, and a login that can neither place the unit nor stand
824	     * the yard it waits on keeps the sibling naked, so the yard is the planner's own pass and not
825	     * a second facility decision here. A sibling that can take the unit but holds nothing is served
826	     * here whatever its exposure, so the wall reaches every planet the account owns.
827	     *
828	     * @return list<QueueableUnit>
829	     */
830	    // QUAL-003: every bare sibling is asked, so the wallet of one is never the reason another stays zero.
831	    public function standingDefenceOrders(int $playerId, ?PlayerService $player = null): array
832	    {
833	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
834	        if ($profile === null || ! User::query()->whereKey($playerId)->exists()) {
835	            return [];
836	        }
837	
838	        $player ??= $this->playerServiceFactory->make($playerId, true);
839	        $planets = $player->planets->all();
840	        if ($planets === [] || ! $this->anyPlanetHoldsDefence($planets)) {
841	            return [];
842	        }
843	
844	        $orders = [];
845	        foreach ($planets as $planet) {
846	            // The balance is refreshed before the wall is priced: the host refuses an unaffordable batch.
847	            $planet->updateResources(false);
848	            if ($this->defenseNeed->standingUnits($planet) > 0) {
849	                continue;
850	            }
851	
852	            $order = $this->standingDefence($player, $planet);
853	            if ($order !== null) {
854	                $orders[] = $order;
855	            }
856	        }
857	
858	        return $orders;
859	    }
