903	    /**
904	     * Whether this order would spend a resource the planet is saving for an economy step: a player
905	     * mines while short, and defence comes from what the economy leaves.
906	     */
907	    private function starvesSaving(PlanetService $planet, AiProfile $profile, UnitObject $unit, int $amount): bool
908	    {
909	        $saving = $this->buildingPlanner->savingFor($planet, $profile);
910	        if ($saving === null) {
911	            return false;
912	        }
913	
914	        $price = ObjectService::getObjectPrice($unit->machine_name, $planet);
915	        $held = $planet->getResources();
916	
917	        foreach (['metal', 'crystal', 'deuterium'] as $resource) {
918	            if ($price->{$resource}->get() > 0 && $saving->{$resource}->get() > 0
919	                && $held->{$resource}->get() - $price->{$resource}->get() * $amount < $saving->{$resource}->get()) {
920	                return true;
921	            }
922	        }
923	
924	        return false;
925	    }
926	
927	    private function metalEquivalent(Resources $resources): float
928	    {
929	        return $resources->metal->get()
930	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
931	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
932	    }
933	}

